class OrderProcessor {
  calculateDiscount(order: Order) {
    const tier = order.customer.getAccount().getLoyalty().getTier();
    if (tier === 'GOLD') return 0.2;
    if (tier === 'SILVER') return 0.1;
    return 0;
  }
}

